Language fundamentals::Variables and val.syntax:
variable "<NAME>" {
  type        = <TYPE>
  default     = <EXPRESSION>
  description = "<DESCRIPTION>"

  validation {
    condition     = <EXPRESSION>
    error_message = "<ERROR_MESSAGE>"
  }
}

example.code:
variable "environment" {
  type        = string
  description = "Deployment environment"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "Environment must be dev, staging, or prod."
  }
}

output "environment" {
  value = var.environment
}

module "network" {
  source = "./modules/network"

  base_cidr_block = "10.0.0.0/8"
}

module "consul_cluster" {
  source = "./modules/consul-cluster"

  vpc_id     = module.network.vpc_id
  subnet_ids = module.network.subnet_ids
}

variable "projects" {
  type = map(object({
    environment = string
    instance_type = string
  }))
  default = {
    alpha = { environment = "dev",  instance_type = "t3.micro" }
    beta  = { environment = "prod", instance_type = "t3.small" }
  }
}

module "app" {
  source = "./modules/app"
  for_each = var.projects

  environment   = each.value.environment
  instance_type = each.value.instance_type
  name          = each.key
}

output "app_names" {
  value = [for key, app in module.app : key]
}

module "network" {
  source = "./modules/network"
}

module "app" {
  source     = "./modules/app"
  subnet_ids = module.network.subnet_ids
}

variable "settings" {
  type = list(object({
    namespace = string
    name      = string
    value     = string
  }))
  default = []
}

resource "example_resource" "example" {
  dynamic "setting" {
    for_each = var.settings
    iterator = item
    content {
      namespace = item.value.namespace
      name      = item.value.name
      value     = item.value.value
    }
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = "example-vpc"
  cidr = "10.0.0.0/16"
}

module "web" {
  source = "./modules/web"

  instance_count = 2
}

# modules/web/variables.tf
variable "instance_count" {
  type = number
}

# modules/web/main.tf
resource "example_server" "web" {
  count = var.instance_count
}

# modules/web/outputs.tf
output "server_ids" {
  value = example_server.web[*].id
}

moved {
  from = aws_instance.a
  to   = aws_instance.b
}

resource "aws_instance" "b" {
  ami           = "ami-0c55b159cbfafé1f0"
  instance_type = "t3.micro"
}

variable "api_token" {
  type      = string
  sensitive = true
}

provider "example" {
  token = var.api_token
}

